options.onMounted:
const _this = this
$api.get('/users/select', { baseURL: '/gateway' }).then(res => {
  res = res.data.data
  const result = []
  res.forEach(item => {
    if(item.value) {
      result.push({
        label: item.label,
        value: item.value
      })
    }
  })
  result.sort((a, b) => a.label.localeCompare(b.label))
  _this.loadOptions(result)
}).catch(err => {
})

const _this = this
const interval = setInterval(() => {
  const vform = _this.getFormRef()
  if(vform.globalOptionData.ready) {
    clearInterval(interval)
    _this.loadOptions(vform.globalOptionData.fileList)
  }
}, 1000)

options.onChange:
const _this = this
const vform = _this.getFormRef()
const interval = setInterval(() => {
  if(vform?.globalOptionData?.ready) {
    clearInterval(interval)
    setData()
  }
}, 1000)


function setData (reset = false) {
  const docType = vform.globalOptionData.fileList.find(item => item.value === value)
  const metaList = docType.keywords.reduce((prev,item) => {
    if(item.type === 'date') prev.push({
      value: item.name,
      label: item.name
    })
    return prev
  }, [])

  let triggerMetaData = _this.getWidgetRef('triggerMetaData' + '@row' + rowId)
  if(reset) triggerMetaData.setValue('')
  triggerMetaData.loadOptions(metaList)
}

