  }
  */
  const _this = this
  if(value) {
    console.log()
    check(value)
  } else {
    callback();  //pass
  }

  async function check(documentType) {
    const id = _this.getWidgetRef('id').getValue()
    let result = await $api.get('/dms/policy/retention/document-type/used',{
      params: {
        documentType,
        id
      }, 
      baseURL:'/admin/api'
    }).then(res => res.data.data)
    result = result.filter(item => item.policyRetentionId !== id)
    if(result && result.length > 0) {
      callback(new Error($t('tip.documentTypeUsed')))
    } else {
      callback();  //pass
    }
}

