getDocTypeList()
async function getDocTypeList() {
  const typeList = await $api.get('/dms/docpal-type/active', {}).then(res => res.data.data)
  typeList.forEach((item) => {
    const keywords = item.keywords ? item.keywords : []
    const _item = {
      keywords: [...defaultKeywords, ...keywords],
      value: item.name,
      label: $t(item.name)
    }
    if(!item.isFolder) {
      _this.globalOptionData.fileList.push(_item)
    }
  })
  setTimeout(() => {
    _this.globalOptionData.ready = true
  }, 1000);
}
